-- MANAGEMENT-PERSONAS-6 / ROADMAP-ORIGINATE-1 (2026-10-26, pillar autonomy). Owner directive 2026-10-26 09:26Z, verbatim: "FLEET MANAGERS SHALL
-- ACTIVELY RESEARCH, BUILD, IMPLEMENT, AND DEPLOY ROADMAPS TO IMPROVE FEATURES, FUNCTIONALITY, AND QUALITY. THE FLEET SHALL ACTIVELY BUILD,
-- IMPLEMENT, DEPLOY, AND TEST NEW FEATURES AND FUNCTIONALITY AUTOMATICALLY"
--
-- Until now the managers only reacted (focus, closes, root causes, lever reviews); every roadmap row came from an issue, failure mode, goal or
-- project somebody else filed. This migration has them originate work on the existing path: an open issue with a code-task line is built by the
-- code loop (RED-DRAIN-1 dispatch or the orchestrator's intake), merged on green checks when its source is a trusted origin, deployed by the
-- canonical path with canary and revert, and verified live (code_tasks merge_state verified).
--
-- WHAT THE MANAGERS' HOURLY TICK NOW ALSO DOES (fleet_tasks management-personas)
--   1. research: once a day each active program manager (not QNFO.PERSONAL: the personal plane stays apart) with fewer than 3 open roadmap items
--      asks the Cloudflare agent to research one new feature or quality improvement from its aim, quality index, worsening metrics, the fleet's
--      papers and its workers' code, answered as TITLE / WHY / code-task / code-anchor / EDIT lines (cf_agent_requests 'roadmap-<program>-<day>').
--   2. proposal: an answer in that form becomes a roadmap_proposals row (v_roadmap_originated); one that names no single worker file the code loop
--      may change (control plane, .github, personal-*) is rejected with the reason.
--   3. build: a proposal becomes a high "ROADMAP-1: <program> #<n>: <title>" issue whose first lines are its code-task and code-anchor lines, so
--      the code loop builds it and roadmap-backlog-sync puts it on the roadmap; persona_actions kind roadmap-originate.
--   4. outcome: roadmap_proposals follows the code task; when it is merged and verified live the managers close the issue with the pull request
--      as evidence (kind roadmap-deployed). Metric roadmap_items_deployed_7d.
--   5. the portfolio brief states proposed, filed, in build and deployed items.
-- Merge admission: the merge runner merges a task only when its source issue is a trusted origin (ops_config code_merge_trusted_sources). Adding
-- "management-personas|ROADMAP-1:" to that list was refused by the session's permission check on 2026-10-26, so this migration does not add it.
-- Until that entry exists, step 3 files nothing (a pull request the runner must refuse would only occupy the code loop) and the proposals wait,
-- listed in v_roadmap_originated and the brief; once the entry exists the next tick files them.
--
-- Stop: INSERT OR REPLACE INTO ops_config (key, value) VALUES ('roadmap_originate', 'off');  (persona_actions = off stops all manager decisions)
-- Verify after apply:
--   SELECT instance, status, substr(result, 1, 200) FROM cf_agent_requests WHERE instance LIKE 'roadmap-%' ORDER BY id DESC;
--   SELECT * FROM v_roadmap_originated ORDER BY id DESC;
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261026_mp6_workflow
-- Rollback: UPDATE fleet_tasks SET definition = (SELECT definition FROM bak_20261026_mp6_workflow WHERE id = 'management-personas'), version = version + 1 WHERE id = 'management-personas'; INSERT OR REPLACE INTO ops_config (key, value) VALUES ('roadmap_originate', 'off');

CREATE TABLE IF NOT EXISTS bak_20261026_mp6_workflow AS SELECT id, definition, version FROM fleet_tasks WHERE id = 'management-personas';

CREATE TABLE IF NOT EXISTS roadmap_proposals (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  program_code TEXT NOT NULL,
  request_instance TEXT UNIQUE,
  title TEXT,
  rationale TEXT,
  path TEXT,
  anchor_line TEXT,
  status TEXT NOT NULL DEFAULT 'proposed',
  issue_id INTEGER,
  task_id TEXT,
  pr_url TEXT,
  outcome TEXT,
  deployed_at TEXT,
  created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  updated_at TEXT
);

DROP VIEW IF EXISTS v_roadmap_originated;
CREATE VIEW v_roadmap_originated AS
SELECT p.id, p.program_code, p.title, p.path, p.status, p.issue_id, p.task_id, p.pr_url, p.outcome, p.created_at, p.deployed_at,
  (SELECT a.status FROM agent_issues a WHERE a.id = p.issue_id) AS issue_status
FROM roadmap_proposals p;

INSERT OR IGNORE INTO ops_config (key, value) VALUES ('roadmap_originate', 'on');

UPDATE fleet_tasks
SET definition = json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(definition, '$.steps[#]', json('{"type": "sql", "name": "rm-research", "db": "AUDIT", "sql": "INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''program-manager:'' || c.program_code, ''run'', ''You are the program manager of '' || c.program_code || '' in the QNFO fleet (repository QNFO/qnfo-workers, Cloudflare Workers plus the D1 database qnfo-audit). The owner asked the managers to research, build and deploy roadmaps that improve features, functionality and quality. Your program''''s aim: '' || COALESCE(c.objective, '''') || '' Its quality index is '' || COALESCE((SELECT quality_index FROM v_metric_improvement_by_program v WHERE v.program_code = c.program_code), ''?'') || '' of 100; metrics worse than 7 days ago: '' || COALESCE((SELECT group_concat(metric_key, '', '') FROM (SELECT metric_key FROM metric_improvement_now m WHERE m.program_code = c.program_code AND m.verdict = ''breach-worsening'' ORDER BY priority LIMIT 5)), ''none'') || ''. Roadmap items already open: '' || COALESCE((SELECT group_concat(substr(title, 1, 90), ''; '') FROM agent_issues i WHERE i.status = ''open'' AND i.title LIKE ''ROADMAP-1: '' || c.program_code || '' #%''), ''none'') || ''. Research it: read qnfo-audit (metric_improvement_now, persona_briefs, agent_issues, roadmap_implementation, the papers the fleet published) and the code of the program''''s workers in the repository. Then propose ONE new feature or quality improvement that a single-file change can deliver and that users or the fleet would notice, not a fix for an open issue. Reply in exactly this form, each on its own line:'' || char(10) || ''TITLE: <under 80 characters>'' || char(10) || ''WHY: <what it improves and how we will see it, under 80 words>'' || char(10) || ''code-task: repo=qnfo-workers path=<one worker.js, never qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-code-orchestrator or .github>'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 120 words>'', ''roadmap-'' || c.program_code || ''-'' || strftime(''%Y%m%d'', ''now''), ''medium'' FROM program_charters c WHERE c.status = ''active'' AND c.program_code <> ''QNFO.PERSONAL'' AND (SELECT COUNT(*) FROM agent_issues i WHERE i.status = ''open'' AND i.title LIKE ''ROADMAP-1: '' || c.program_code || '' #%'') < 3 AND NOT EXISTS (SELECT 1 FROM cf_agent_requests r WHERE r.instance = ''roadmap-'' || c.program_code || ''-'' || strftime(''%Y%m%d'', ''now'') AND (r.status IN (''queued'', ''running'') OR (r.status = ''done'' AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%'' AND COALESCE(r.result, '''') <> ''''))) AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''roadmap_originate''), ''on'') <> ''off''"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-parse", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO roadmap_proposals (program_code, request_instance, title, rationale, path, anchor_line, status, created_at, updated_at) SELECT substr(r.requester, 17), r.instance, substr(trim(substr(trim(replace(CASE WHEN instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''TITLE:'')), char(10)) > 0 THEN substr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''TITLE:'')), 1, instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''TITLE:'')), char(10)) - 1) ELSE substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''TITLE:'')) END, char(13), ''''), '' `*''), 7)), 1, 120), substr(replace(replace(r.result, ''code-task:'', ''code task:''), ''code-anchor:'', ''code anchor:''), 1, 1500), trim(CASE WHEN instr(substr(trim(replace(CASE WHEN instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) > 0 THEN substr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), 1, instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) - 1) ELSE substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')) END, char(13), ''''), '' `*''), instr(trim(replace(CASE WHEN instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) > 0 THEN substr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), 1, instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) - 1) ELSE substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')) END, char(13), ''''), '' `*''), ''path='') + 5) || '' '', '' '') > 0 THEN substr(substr(trim(replace(CASE WHEN instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) > 0 THEN substr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), 1, instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) - 1) ELSE substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')) END, char(13), ''''), '' `*''), instr(trim(replace(CASE WHEN instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) > 0 THEN substr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), 1, instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) - 1) ELSE substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')) END, char(13), ''''), '' `*''), ''path='') + 5), 1, instr(substr(trim(replace(CASE WHEN instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) > 0 THEN substr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), 1, instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) - 1) ELSE substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')) END, char(13), ''''), '' `*''), instr(trim(replace(CASE WHEN instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) > 0 THEN substr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), 1, instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')), char(10)) - 1) ELSE substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-task:'')) END, char(13), ''''), '' `*''), ''path='') + 5) || '' '', '' '') - 1) END, '' `*''), ''code-anchor: '' || substr(trim(substr(trim(replace(CASE WHEN instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-anchor:'')), char(10)) > 0 THEN substr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-anchor:'')), 1, instr(substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-anchor:'')), char(10)) - 1) ELSE substr(replace(r.result, ''**'', ''''), instr(replace(r.result, ''**'', ''''), ''code-anchor:'')) END, char(13), ''''), '' `*''), 13), '' `''), 1, 300), ''proposed'', strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') FROM cf_agent_requests r WHERE r.instance LIKE ''roadmap-%'' AND r.status = ''done'' AND instr(r.result, ''TITLE:'') > 0 AND instr(r.result, ''code-task:'') > 0 AND instr(r.result, ''code-anchor:'') > 0"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-reject", "db": "AUDIT", "sql": "UPDATE roadmap_proposals SET status = ''rejected'', outcome = ''not a single worker file the code loop may change: '' || COALESCE(path, ''(none)''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') WHERE status = ''proposed'' AND (path IS NULL OR path NOT LIKE ''%/%.%'' OR instr(path, '' '') > 0 OR instr(path, ''..'') > 0 OR path LIKE ''.github/%'' OR EXISTS (SELECT 1 FROM json_each(''[\"qnfo-fleet-control/\",\"qnfo-ops/\",\"qnfo-deploy-guard/\",\"qnfo-containers-pilot/\",\"qnfo-autonomy-scorer/\",\"qnfo-observability/\",\"qnfo-code-orchestrator/\",\"qnfo-code-agent/\",\"personal-\"]'') d WHERE instr(roadmap_proposals.path, d.value) = 1) OR length(anchor_line) < 20 OR title = '''')"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-file", "db": "AUDIT", "sql": "INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''ROADMAP-1: '' || p.program_code || '' #'' || p.id || '': '' || p.title, ''code-task: repo=qnfo-workers path='' || p.path || char(10) || p.anchor_line || char(10) || char(10) || ''Manager-originated roadmap item (ROADMAP-ORIGINATE-1, owner directive 2026-10-26: the fleet managers research, build, implement and deploy roadmaps that improve features, functionality and quality). Proposed by the program manager of '' || p.program_code || '' from Cloudflare agent research ('' || p.request_instance || '').'' || char(10) || ''Definition of done: the change is merged and verified live by the canonical deploy (code_tasks merge_state verified); the managers then close this issue with the pull request as evidence and record the outcome in roadmap_proposals.'' || char(10) || char(10) || p.rationale, ''management-personas'', ''feature'', ''high'', ''open'', CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000, CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 FROM roadmap_proposals p WHERE p.status = ''proposed'' AND (SELECT COUNT(*) FROM agent_issues i WHERE i.status = ''open'' AND i.title LIKE ''ROADMAP-1: '' || p.program_code || '' #%'') < 3 AND NOT EXISTS (SELECT 1 FROM agent_issues i WHERE i.title LIKE ''ROADMAP-1: '' || p.program_code || '' #'' || p.id || '':%'') AND instr(COALESCE((SELECT value FROM ops_config WHERE key = ''code_merge_trusted_sources''), ''''), ''management-personas|ROADMAP-1:'') > 0 AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''roadmap_originate''), ''on'') <> ''off''"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-filed", "db": "AUDIT", "sql": "UPDATE roadmap_proposals SET status = ''filed'', issue_id = (SELECT MIN(i.id) FROM agent_issues i WHERE i.title LIKE ''ROADMAP-1: '' || roadmap_proposals.program_code || '' #'' || roadmap_proposals.id || '':%''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') WHERE status = ''proposed'' AND (SELECT MIN(i.id) FROM agent_issues i WHERE i.title LIKE ''ROADMAP-1: '' || roadmap_proposals.program_code || '' #'' || roadmap_proposals.id || '':%'') IS NOT NULL"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-map", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO issue_project_map (issue_id, project_code, program_code, kind, updated_at) SELECT p.issue_id, ''W.'' || p.program_code, p.program_code, ''feature'', datetime(''now'') FROM roadmap_proposals p WHERE p.issue_id IS NOT NULL"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-filed-log", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''program-manager:'' || p.program_code, ''roadmap-originate'', p.issue_id, ''proposal #'' || p.id, ''filed'', ''roadmap item '' || p.title || '' ('' || p.path || '') researched by the Cloudflare agent ('' || p.request_instance || '')'' FROM roadmap_proposals p WHERE p.status = ''filed'' AND NOT EXISTS (SELECT 1 FROM persona_actions a WHERE a.kind = ''roadmap-originate'' AND a.issue_id = p.issue_id)"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-track", "db": "AUDIT", "sql": "UPDATE roadmap_proposals SET task_id = (SELECT t.id FROM code_tasks t WHERE t.id = ''ct_im'' || roadmap_proposals.issue_id OR t.goal LIKE ''[issue #'' || roadmap_proposals.issue_id || '']%'' ORDER BY CASE WHEN t.status = ''merged'' THEN 0 ELSE 1 END, t.updated_at DESC LIMIT 1), status = CASE WHEN status = ''filed'' THEN ''building'' ELSE status END, outcome = (SELECT t.status || COALESCE(''/'' || t.merge_state, '''') || COALESCE('': '' || substr(t.last_error, 1, 160), '''') FROM code_tasks t WHERE t.id = (SELECT t.id FROM code_tasks t WHERE t.id = ''ct_im'' || roadmap_proposals.issue_id OR t.goal LIKE ''[issue #'' || roadmap_proposals.issue_id || '']%'' ORDER BY CASE WHEN t.status = ''merged'' THEN 0 ELSE 1 END, t.updated_at DESC LIMIT 1)), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') WHERE status IN (''filed'', ''building'') AND (SELECT t.id FROM code_tasks t WHERE t.id = ''ct_im'' || roadmap_proposals.issue_id OR t.goal LIKE ''[issue #'' || roadmap_proposals.issue_id || '']%'' ORDER BY CASE WHEN t.status = ''merged'' THEN 0 ELSE 1 END, t.updated_at DESC LIMIT 1) IS NOT NULL"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-deployed-evidence", "db": "AUDIT", "sql": "INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT issue_id, ''deployed'', ''triaged'', ''management-personas'', datetime(''now''), ''manager-originated roadmap item merged and verified live: '' || COALESCE(pr_url, task_id) || '' (code task '' || task_id || '', merge_state verified)'' FROM (SELECT p.id, p.issue_id, p.program_code, t.id AS task_id, t.pr_url FROM roadmap_proposals p JOIN code_tasks t ON t.id = p.task_id JOIN agent_issues a ON a.id = p.issue_id WHERE p.status = ''building'' AND t.status = ''merged'' AND t.merge_state = ''verified'' AND a.status = ''open'') WHERE 1 ON CONFLICT(issue_id) DO UPDATE SET close_evidence = excluded.close_evidence"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-deployed-log", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''program-manager:'' || program_code, ''roadmap-deployed'', issue_id, ''building'', ''deployed'', ''merged and verified live: '' || COALESCE(pr_url, task_id) FROM (SELECT p.id, p.issue_id, p.program_code, t.id AS task_id, t.pr_url FROM roadmap_proposals p JOIN code_tasks t ON t.id = p.task_id JOIN agent_issues a ON a.id = p.issue_id WHERE p.status = ''building'' AND t.status = ''merged'' AND t.merge_state = ''verified'' AND a.status = ''open'')"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-deployed-contracts", "db": "AUDIT", "sql": "UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:roadmap-item-deployed'', last_attempt_at = datetime(''now'') WHERE issue_id IN (SELECT issue_id FROM (SELECT p.id, p.issue_id, p.program_code, t.id AS task_id, t.pr_url FROM roadmap_proposals p JOIN code_tasks t ON t.id = p.task_id JOIN agent_issues a ON a.id = p.issue_id WHERE p.status = ''building'' AND t.status = ''merged'' AND t.merge_state = ''verified'' AND a.status = ''open'')) AND status IN (''active'', ''holding'', ''needs-machine-probe'', ''probe-review-refused'')"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-deployed-close", "db": "AUDIT", "sql": "UPDATE agent_issues SET status = ''closed'', close_channel = ''auto:management-personas'', updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE id IN (SELECT issue_id FROM (SELECT p.id, p.issue_id, p.program_code, t.id AS task_id, t.pr_url FROM roadmap_proposals p JOIN code_tasks t ON t.id = p.task_id JOIN agent_issues a ON a.id = p.issue_id WHERE p.status = ''building'' AND t.status = ''merged'' AND t.merge_state = ''verified'' AND a.status = ''open''))"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-deployed", "db": "AUDIT", "sql": "UPDATE roadmap_proposals SET status = ''deployed'', pr_url = (SELECT t.pr_url FROM code_tasks t WHERE t.id = roadmap_proposals.task_id), outcome = ''merged and verified live'', deployed_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') WHERE status = ''building'' AND EXISTS (SELECT 1 FROM code_tasks t WHERE t.id = roadmap_proposals.task_id AND t.status = ''merged'' AND t.merge_state = ''verified'') AND EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = roadmap_proposals.issue_id AND a.status = ''closed'')"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-metric", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM roadmap_proposals WHERE status = ''deployed'' AND deployed_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''roadmap_items_deployed_7d''"}')), '$.steps[#]', json('{"type": "sql", "name": "rm-brief", "db": "AUDIT", "sql": "UPDATE persona_briefs SET summary = summary || '' Roadmap (manager-originated): '' || (SELECT COUNT(*) FROM roadmap_proposals WHERE status = ''proposed'') || '' proposed'' || CASE WHEN instr(COALESCE((SELECT value FROM ops_config WHERE key = ''code_merge_trusted_sources''), ''''), ''management-personas|ROADMAP-1:'') = 0 THEN '' (waiting for merge admission of management-personas ROADMAP-1 items in code_merge_trusted_sources)'' ELSE '''' END || '', '' || (SELECT COUNT(*) FROM roadmap_proposals WHERE status = ''filed'') || '' filed, '' || (SELECT COUNT(*) FROM roadmap_proposals WHERE status = ''building'') || '' in build, '' || (SELECT COUNT(*) FROM roadmap_proposals WHERE status = ''deployed'' AND deployed_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'')) || '' deployed in 7 days'' || COALESCE('' (latest: '' || (SELECT title FROM roadmap_proposals WHERE status = ''deployed'' ORDER BY deployed_at DESC LIMIT 1) || '')'', '''') || ''.'' WHERE persona_key = ''portfolio-manager'' AND tick = (SELECT MAX(tick) FROM portfolio_allocations) AND summary NOT LIKE ''%Roadmap (manager-originated):%''"}')),
  version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE id = 'management-personas' AND instr(definition, '"rm-research"') = 0;

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, target, owner, disposition_actor, refresh_cadence, state) VALUES
  ('roadmap_items_deployed_7d', 'operational', 'target',
   'manager-originated roadmap items (roadmap_proposals) merged and verified live in the last 7 days. Trigger exemption: the managers research, file and close these items themselves every hour (MANAGEMENT-PERSONAS-6) and the portfolio brief reports the count, which is the action a trigger would take',
   'qnfo-audit.roadmap_proposals (MANAGEMENT-PERSONAS-6), written hourly by fleet_tasks management-personas', '>= 3 a week', 'qnfo-fleet-control', 'agent:management-personas', 'hourly', 'PENDING');

INSERT OR IGNORE INTO capability_ledger (capability, provenance, prerequisites, reliability, acquired_at, evidence)
VALUES ('managers-originate-roadmap', 'migrations/2026-10-26-management-personas-6.sql (ROADMAP-ORIGINATE-1)', 'fleet_tasks management-personas, cf_agent_requests, code loop intake and RED-DRAIN-1 dispatch, canonical deploy', 0.5, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
